function help.search(query, textMatches)
  local r = {}
  for _, t in ipairs(help.topics) do
    if textMatches(t.title .. ' ' .. t.text .. ' ' .. (t.keywords or ''), query) then r[#r + 1] = t end
  end
  return r
end

return help
